chrome.runtime.onInstalled.addListener(()=>{console.log("[CampusApply] 插件已安装/更新"),chrome.contextMenus.create({id:"campus-apply-fill-field",title:"🤖 智能填充此字段",contexts:["editable"]}),chrome.contextMenus.create({id:"campus-apply-fill-page",title:"📋 一键填充整页",contexts:["page"]})});chrome.contextMenus.onClicked.addListener((e,r)=>{r!=null&&r.id&&(e.menuItemId==="campus-apply-fill-field"?chrome.tabs.sendMessage(r.id,{type:"FILL_SINGLE_FIELD"}):e.menuItemId==="campus-apply-fill-page"&&chrome.tabs.sendMessage(r.id,{type:"FILL_ALL_FIELDS"}))});chrome.runtime.onMessage.addListener((e,r,a)=>{switch(e.type){case"OPEN_SIDEBAR":chrome.sidePanel.setOptions({enabled:!0}),e.tabId&&chrome.sidePanel.open({tabId:e.tabId}),a({success:!0});break;case"GET_ACTIVE_TAB":return chrome.tabs.query({active:!0,currentWindow:!0},t=>{a({tab:t[0]})}),!0;case"SCAN_PAGE":if(e.tabId)return chrome.tabs.sendMessage(e.tabId,{type:"SCAN_FORM_FIELDS"},t=>{a(t)}),!0;break;case"FILL_FIELDS":if(e.tabId)return chrome.tabs.sendMessage(e.tabId,{type:"EXECUTE_FILL",data:e.data},t=>{a(t)}),!0;break;case"CLEAR_FILLED":if(e.tabId)return chrome.tabs.sendMessage(e.tabId,{type:"CLEAR_ALL_FILLED"},t=>{a(t)}),!0;break}});chrome.action.onClicked.addListener(e=>{e.id&&chrome.sidePanel.open({tabId:e.id})});
